1	#!/usr/bin/env bun
2	/**
3	 * resolve_pr_branch.ts — the head branch of the pull request a `pr` run is on.
4	 *
5	 * A `pr` run checks the pull request out through `refs/pull/N/head`, and that is
6	 * not a branch: `actions/checkout` fetches it to `refs/remotes/pull/N/head` and
7	 * checks *that* out, so git leaves the run detached and
8	 * `git rev-parse --abbrev-ref HEAD` answers `HEAD`. There was therefore nothing
9	 * for `commit_and_push` to push to, and it built a refspec out of git's own
10	 * description of the state --
11	 *
12	 *     fatal: invalid refspec '(HEAD detached at pull/802/head)'
13	 *
14	 * -- so the one agent whose job is to push a fix onto a red pull request was the
15	 * one that could not. Observed twice: #247, and the run that filed #803.
16	 *
17	 * This is the counterpart of `resolve_issue_branch.ts`. It answers *which* branch
18	 * the pull request is already from; the workflow step beside it materialises that
19	 * branch at the commit the run already has. A script rather than inline bash
20	 * because the decision is the part that can be wrong, and this way it is decided
21	 * where it can be tested without a runner.
22	 *
23	 * Best-effort, in the same way and for the same reason: nothing here fails the
24	 * run. An empty `branch` output means this run has no branch it may push to, it
25	 * stays on the detached checkout, and the tool that needs a branch refuses with a
26	 * message saying what the run cannot do. Stopping before the agent has said
27	 * anything would be worse than that.
28	 *
29	 * Usage:
30	 *   resolve_pr_branch.ts --repo owner/name --number 12
31	 *
32	 * Writes `branch=<name-or-empty>` to $GITHUB_OUTPUT.
33	 */
34	import { appendFileSync } from "node:fs";
35	import { parseArgs } from "node:util";
36	import { gh, gitRun } from "../../adapters/github/gh.ts";
37	import { defineScript } from "./lib/script-ref.ts";
38	
39	export interface ResolvePrBranchArgs {
40	  repo: string;
41	  number: string;
42	}
43	
44	export const ref = defineScript<ResolvePrBranchArgs>(import.meta.url);
45	
46	function log(message: string): void {
47	  console.error(`[atomaton-pr-branch] ${message}`);
48	}
49	
50	/** What `gh pr view` was asked for, and what an unreadable answer means. */
51	export interface PrHead {
52	  branch: string;
53	  /** True when the head branch lives in a fork rather than in this repository. */
54	  crossRepository: boolean;
55	}
56	
57	/**
58	 * Read the head branch out of `gh pr view --json headRefName,isCrossRepository`.
59	 *
60	 * Pure, and forgiving on purpose: an answer that cannot be parsed is one of the
61	 * ways this run ends up with no branch, not an exception. The fork flag is
62	 * carried separately from the name because the two refusals are different facts
63	 * about the pull request, and whoever reads the log needs to tell them apart.
64	 */
65	export function prHead(prJson: string): PrHead {
66	  try {
67	    const pr = JSON.parse(prJson) as { headRefName?: unknown; isCrossRepository?: unknown };
68	    return {
69	      branch: typeof pr.headRefName === "string" ? pr.headRefName.trim() : "",
70	      crossRepository: pr.isCrossRepository === true,
71	    };
72	  } catch {
73	    return { branch: "", crossRepository: false };
74	  }
75	}
76	
77	/**
78	 * Whether a name may be checked out as a branch, asked of git rather than
79	 * pattern-matched.
80	 *
81	 * `check-ref-format --branch` is the same rule `git checkout` and `git push`
82	 * apply, so a name it accepts cannot be one they refuse, and one it rejects never
83	 * reaches the `git checkout` the caller runs. That covers the empty name; `HEAD`
84	 * — not a branch, and exactly what the step this replaces used to write; names
85	 * carrying whitespace or a control character, which would otherwise split into
86	 * extra refspecs or extra `$GITHUB_ENV` lines; and `..`, `~`, `^`, `:`, `\`,
87	 * `@{`, `.lock` or a leading `-`.
88	 */
89	export function isBranchName(name: string): boolean {
90	  if (!name) return false;
91	  return gitRun("check-ref-format", "--branch", name).code === 0;
92	}
93	
94	/**
95	 * Whether the branch is one `origin` has.
96	 *
97	 * A pull request's `headRefName` names a branch in its head repository, which for
98	 * a fork is not `origin`. Asking first is what turns "the checkout fails" into
99	 * "this run stays detached", and it is what stops a fork's branch from being
100	 * taken for a branch of the same name in this repository -- which is the branch a
101	 * push would then land on.
102	 */
103	export function existsOnOrigin(name: string): boolean {
104	  const { code, stdout } = gitRun("ls-remote", "--heads", "origin", `refs/heads/${name}`);
105	  return code === 0 && stdout.trim() !== "";
106	}
107	
108	function main(): void {
109	  const { values } = parseArgs({
110	    args: Bun.argv.slice(2),
111	    options: { repo: { type: "string" }, number: { type: "string" } },
112	  });
113	
114	  const repo = (values.repo ?? "").trim();
115	  const number = Number((values.number ?? "").trim());
116	  const githubOutput = process.env.GITHUB_OUTPUT;
117	
118	  // Never exits non-zero. Every path below either resolves a name or resolves
119	  // nothing, and says on stderr which of the two happened and why.
120	  let branch = "";
121	  if (!repo || !Number.isInteger(number) || number <= 0) {
122	    log("missing --repo or --number; this run has no branch to check out");
123	  } else {
124	    const { code, stdout, stderr } = gh(
125	      "pr", "view", String(number), "--repo", repo,
126	      "--json", "headRefName,isCrossRepository",
127	    );
128	    if (code !== 0) {
129	      log(`could not read pull request #${number}: ${stderr || stdout}`);
130	    } else {
131	      const head = prHead(stdout);
132	      if (head.crossRepository) {
133	        log(
134	          `pull request #${number} comes from a fork, so its head branch is not a branch of this repository; ` +
135	            "this run stays on the detached checkout",
136	        );
137	      } else if (!head.branch) {
138	        log(`pull request #${number} names no head branch`);
139	      } else if (!isBranchName(head.branch)) {
140	        log(`pull request #${number} names '${head.branch}', which is not a branch name`);
141	      } else if (!existsOnOrigin(head.branch)) {
142	        log(`'${head.branch}' does not exist on origin; this run stays on the detached checkout`);
143	      } else {
144	        branch = head.branch;
145	      }
146	    }
147	  }
148	
149	  log(
150	    branch
151	      ? `the pull request's head branch is ${branch}`
152	      : "no head branch to check out; staying on the detached checkout",
153	  );
154	  if (githubOutput) appendFileSync(githubOutput, `branch=${branch}\n`);
155	}
156	
157	if (import.meta.main) main();

