1	#!/usr/bin/env bun
2	/**
3	 * guard_command_on_closed.ts — a slash command on a closed issue or pull request does
4	 * not start an agent.
5	 *
6	 * Starting work on something somebody has closed is the machinery disagreeing with a
7	 * decision rather than acting on one, and until now it did that quietly: `/engineer`
8	 * on a closed issue dispatched a run exactly as it would on an open one.
9	 *
10	 * ## Why the comment is left alone
11	 *
12	 * `guard_comment_during_run.ts` deletes the comment it catches, because that comment
13	 * would otherwise race a running agent and end up in its context. Nothing is running
14	 * here and nothing is racing, so deleting somebody's words would cost something and
15	 * buy nothing. The command does not run; the comment stays.
16	 *
17	 * ## Why `/stop` is exempt
18	 *
19	 * An agent can close the issue it is working on and keep going — that is a normal
20	 * path — so a closed issue can still have a run on it. Refusing `/stop` there would
21	 * take away the only way to stop that run, which is the one moment the command exists
22	 * for. The in-progress guard carves out the same exception for the same reason.
23	 *
24	 * Usage:
25	 *   guard_command_on_closed.ts --number N --commenter LOGIN --command /engineer
26	 * Writes `blocked=true|false` to $GITHUB_OUTPUT.
27	 */
28	import { appendFileSync } from "node:fs";
29	import { parseArgs } from "node:util";
30	import { gh } from "../../adapters/github/gh.ts";
31	import { LLM_CONTEXT_TAG } from "../../adapters/github/tags.ts";
32	import { readTargetState } from "../../adapters/github/target-state.ts";
33	import { commandOnClosedNotice, mayStartWorkOn } from "../../domain/work/closed-target.ts";
34	import { defineScript } from "./lib/script-ref.ts";
35	
36	export interface GuardCommandOnClosedArgs {
37	  number: string | number;
38	  commenter: string;
39	  command: string;
40	}
41	
42	export const ref = defineScript<GuardCommandOnClosedArgs>(import.meta.url);
43	
44	function main(): void {
45	  const { values } = parseArgs({
46	    args: Bun.argv.slice(2),
47	    options: {
48	      number: { type: "string" },
49	      commenter: { type: "string" },
50	      command: { type: "string" },
51	    },
52	  });
53	
54	  if (!values.number) {
55	    console.error("usage: guard_command_on_closed.ts --number N --commenter LOGIN --command /agent");
56	    process.exit(2);
57	  }
58	
59	  const repo = process.env.GITHUB_REPOSITORY ?? "";
60	  const number = Number(values.number);
61	  const command = (values.command ?? "").trim() || "the command";
62	  const githubOutput = process.env.GITHUB_OUTPUT;
63	  const say = (blocked: boolean) => {
64	    if (githubOutput) appendFileSync(githubOutput, `blocked=${blocked}\n`);
65	  };
66	
67	  const state = readTargetState(number, repo);
68	  if (mayStartWorkOn(state)) {
69	    say(false);
70	    return;
71	  }
72	
73	  // Tagged out of the model's context like every other notice addressed to a person.
74	  // A run may still be going on a closed issue — an agent can close its own — and an
75	  // untagged copy would be read by that agent as an instruction, when what it says is
76	  // that somebody else's command was refused.
77	  const posted = gh(
78	    "issue", "comment", String(number), "--repo", repo,
79	    "--body", [LLM_CONTEXT_TAG.write("exclude"), commandOnClosedNotice(values.commenter ?? "", command, state, number)].join("\n"),
80	  );
81	  if (posted.code !== 0) {
82	    console.error(`Warning: could not post the refusal on #${number}: ${posted.stderr || posted.stdout}`);
83	  }
84	
85	  say(true);
86	  console.error(
87	    `Refused '${command}' on #${number}: ${!state.known ? `state unreadable (${state.why})` : "not open"}.`,
88	  );
89	}
90	
