/**
 * pr-head-branch.ts — the one place a pull request's head branch is resolved from
 * GitHub, and the three answers that make it usable here.
 *
 * Moved out of `resolve_pr_branch.ts` unchanged when a second entrance needed it:
 * a person's `/agent` comment on a pull request read `gh pr view --json headRefName`
 * inline and dispatched validation with whatever came back (#344). ...
 */
import { gh, gitRun } from "../../../adapters/github/gh.ts";
import type { PrHeadRefusal } from "../../../domain/work/pr-head-branch.ts";

export interface PrHead { branch: string; crossRepository: boolean }

export function prHead(prJson: string): PrHead { ... }

export function isBranchName(name: string): boolean { ... }

export function existsOnOrigin(name: string): boolean { ... }

export interface PrHeadResolution {
  /** The branch, or "" when no branch was resolved. */
  branch: string;
  /** The fact that stopped it, or null when there is a branch. */
  refusal: PrHeadRefusal | null;
}

export function resolvePrHeadBranch(repo: string, number: number): PrHeadResolution {
  const { code, stdout, stderr } = gh("pr", "view", String(number), "--repo", repo, "--json", "headRefName,isCrossRepository");
  if (code !== 0) return { branch: "", refusal: { kind: "unreadable", detail: stderr || stdout } };
  const head = prHead(stdout);
  if (head.crossRepository) return { branch: "", refusal: { kind: "fork" } };
  if (!head.branch) return { branch: "", refusal: { kind: "no-branch" } };
  if (!isBranchName(head.branch)) return { branch: "", refusal: { kind: "not-a-branch-name", branch: head.branch } };
  if (!existsOnOrigin(head.branch)) return { branch: "", refusal: { kind: "not-on-origin", branch: head.branch } };
  return { branch: head.branch, refusal: null };
}
```

